  bes,8. f'16 r8 c'8-> ~ c2
  d,8. a'16 r8 e'8->( ~ e4 c4)
  bes,8. f'16 r8 c'8-> ~ c2
  g,8. d'16 r8 a'8->( ~ a4 f4)
}
